import pandas as pd

orders = pd.DataFrame({
    "price": [250, 80, 500, 120],
    "quantity": [2, 5, 1, 3],
    "is_vip": [True, False, True, False],
})

def column_range(col):
    return col.max() - col.min()

print(orders[["price", "quantity"]].apply(column_range))
# price       420
# quantity      4
# dtype: int64

def apply_tiered_tax(price):
    """Apply a higher tax rate to more expensive items."""
    if price > 300:
        return price * 1.25
    elif price > 100:
        return price * 1.18
    return price * 1.05

orders["price_with_tax"] = orders["price"].apply(apply_tiered_tax)

def discounted_price(row):
    if row["is_vip"]:
        return row["price"] * 0.85
    elif row["quantity"] >= 3:
        return row["price"] * 0.90
    return row["price"]

orders["final_price"] = orders.apply(discounted_price, axis=1)
